    return request
            .map(req -> repository.find(req.paymentId()))     // JDBC, about 30 ms
            .map(PaymentView::from);
}

Mono<PaymentView> view(Mono<PaymentRequest> request) {
    return request
            .flatMap(req -> Mono.fromCallable(() -> repository.find(req.paymentId()))   // 1. wrap the blocking call
                    .subscribeOn(Schedulers.boundedElastic()))                          // 2. run it off the I/O thread
            .map(PaymentView::from);                                                    // 3. continues on boundedElastic
}

@Test
void lookupRunsOnBoundedElastic() {
    AtomicReference<String> thread = new AtomicReference<>();
    repository.onFind(() -> thread.set(Thread.currentThread().getName()));
    Mono<PaymentRequest> request = Mono.delay(Duration.ofMillis(5))          // 4. arrive on a non-blocking thread,
            .thenReturn(new PaymentRequest("pay-1"));                        //    like the real server does

    StepVerifier.create(handler.view(request)).expectNextCount(1).verifyComplete();
    assertThat(thread.get()).startsWith("boundedElastic-");
}

